using OcctSharp.Generator.Emission;
using OcctSharp.Generator.Model;
using OcctSharp.Generator.Transformation;
namespace OcctSharp.Generator.Tests;
public sealed class BooleanRepairAdapterContractTests {
 static ClosedWorkflowOperationContract Contract=>ClosedWorkflowOperationContract.BooleanRepairAdapters;
 static BindingDeclaration Row(CopiedCollectionOperationContract.Operation op){string owner=op.NativeName.Split("::")[0];return new(op.StableId,op.NativeName,op.NativeName.EndsWith("::"+owner,StringComparison.Ordinal)?BindingDeclarationKind.Constructor:BindingDeclarationKind.Method,owner+".hxx",1,1){NativeSignature=op.Signature,Access=BindingAccess.Public,SupportState=op.NativeName=="BRepBuilderAPI_Command::IsDone"?BindingSupportState.Manual:BindingSupportState.Pending};}
 [Fact] public void ExactBooleanRepairClosureRejectsSignatureAccessAndUnsafeDrift(){foreach(var op in Contract.Operations.Values){var row=Row(op);Assert.True(Contract.Contains(row));Assert.False(Contract.Contains(row with{NativeSignature=row.NativeSignature+" "}));Assert.False(Contract.Contains(row with{IsTemplated=true}));Assert.False(Contract.Contains(row with{Access=BindingAccess.Private}));if(!op.Supporting)Assert.False(Contract.Contains(row with{SupportState=BindingSupportState.Manual}));}Assert.Throws<InvalidDataException>(()=>ClosedWorkflowOperationEmitter.Emit("8.0.1",new([Row(Contract.Operations.Values.First(o=>!o.Supporting))]),Contract));}
 [Fact] public void NativeHeaderCopiesAreDeterministicAndManualSupportGetsNoEmissionCredit(){var rows=Contract.Operations.Values.Select(Row).ToArray();var a=ClosedWorkflowOperationEmitter.Emit("8.0.1",new(rows),Contract);var b=ClosedWorkflowOperationEmitter.Emit("8.0.1",new(rows.Reverse()),Contract);Assert.Single(a.Files);Assert.Equal(a.Files[0].Content,b.Files[0].Content);Assert.Equal(20,a.SourceStableIds.Count);var manual=rows.Single(d=>d.SupportState==BindingSupportState.Manual);Assert.DoesNotContain(manual.StableId,a.SourceStableIds);Assert.Contains("// Source: "+manual.StableId,a.Files[0].Content);Assert.Contains("std::vector<TopoDS_Shape> Modified",a.Files[0].Content);Assert.Contains("Limit=65536",a.Files[0].Content);Assert.DoesNotContain("OCCTSHARP_CALL",a.Files[0].Content);}
 [Fact] public void SupportingSignaturesAloneCannotPublishBooleanRepairAdapters(){var output=ClosedWorkflowOperationEmitter.Emit("8.0.1",new(Contract.Operations.Values.Where(o=>o.Supporting).Select(Row)),Contract);Assert.Empty(output.Files);Assert.Empty(output.SourceStableIds);}
}
